    stack = []
    for x in d:
        while drop and stack and stack[-1] < x:
            stack.pop(); drop -= 1
        stack.append(x)
    return stack[:t]

def merge(x, y):
    out = []
    while x or y:
        out.append((x if x > y else y).pop(0))   # compare the remaining parts as lists
    return out

