import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] pickDigits(long[] d, int t) {
        int drop = d.length - t;
        int[] st = new int[d.length];
        int top = 0;
        for (long x : d) {
            while (drop > 0 && top > 0 && st[top - 1] < x) {
                top--;
                drop--;
            }
            st[top++] = (int) x;
        }
        int[] res = new int[t];
        for (int i = 0; i < t; i++) res[i] = st[i];
        return res;
    }

    static boolean suffixGreater(int[] x, int i, int[] y, int j) {
        while (i < x.length && j < y.length) {
            if (x[i] != y[j]) return x[i] > y[j];
            i++;
            j++;
        }
        return (x.length - i) > (y.length - j);
    }

    static int[] mergeDigits(int[] x, int[] y) {
        int[] out = new int[x.length + y.length];
        int i = 0, j = 0, o = 0;
        while (i < x.length || j < y.length) {
            if (suffixGreater(x, i, y, j)) out[o++] = x[i++];
            else out[o++] = y[j++];
        }
        return out;
    }

    public static void main(String[] args) throws IOException {
        long p = Long.parseLong(next());
        long q = Long.parseLong(next());
        long k = Long.parseLong(next());
        long[] a = new long[(int) p];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[] b = new long[(int) q];
        for (int i = 0; i < b.length; i++) b[i] = Long.parseLong(next());

        int kk = (int) k;
        int[] best = null;
        for (int i = Math.max(0, kk - (int) q); i <= Math.min(kk, (int) p); i++) {
            int[] cand = mergeDigits(pickDigits(a, i), pickDigits(b, kk - i));
            boolean better = best == null;
            for (int t = 0; !better && t < kk; t++) {
                if (cand[t] != best[t]) {
                    better = cand[t] > best[t];
                    break;
                }
            }
            if (better) best = cand;
        }
        StringBuilder out = new StringBuilder();
        for (int d : best) out.append(d);
        System.out.println(out);
    }
}
